extra_style:
.bass-display{font-size:3.25rem;font-weight:700;font-family:'JetBrains Mono',ui-monospace,monospace;color:var(--amber);line-height:1.1;}
.freq-badge{display:inline-block;padding:.3rem .8rem;border-radius:999px;background:var(--amber-dim);color:var(--amber);font-size:12px;font-weight:600;font-family:'JetBrains Mono',ui-monospace,monospace;}
.bass-visualizer{height:200px;background:var(--panel-2);border:1px solid var(--border);border-radius:4px;display:flex;align-items:flex-end;justify-content:center;gap:4px;padding:1.25rem;}
.bass-bar{width:20px;background:linear-gradient(to top, var(--amber), transparent);border-radius:4px 4px 0 0;transition:height .1s ease;}
.form-range{width:100%;accent-color:var(--amber);height:1.4rem;cursor:pointer;}
.btn-success{background:var(--success);color:#fff;}
.freq-btn{font-size:1.05rem;}

script:
document.addEventListener('DOMContentLoaded', function() {
  const freqSlider = document.getElementById('freq-slider');
  const freqDisplay = document.getElementById('freq-display');
  const freqLabel = document.getElementById('freq-label');
  const volumeSlider = document.getElementById('volume-slider');
  const volumeDisplay = document.getElementById('volume-display');
  const playBtn = document.getElementById('play-btn');
  const freqBtns = document.querySelectorAll('.freq-btn');
  const sweepBtn = document.getElementById('sweep-btn');
  const sweepProgress = document.getElementById('sweep-progress');
  const sweepProgressContainer = document.getElementById('sweep-progress-container');
  const bassBars = document.querySelectorAll('.bass-bar');

  let audioContext = null;
  let oscillator = null;
  let gainNode = null;
  let isPlaying = false;
  let isSweeping = false;
  let animationId = null;

  function getFreqLabel(freq) {
    if (freq <= 30) return 'Sub-bass';
    if (freq <= 60) return 'Deep bass';
    if (freq <= 100) return 'Bass';
    return 'Upper bass';
  }

  function updateDisplay(freq) {
    freqDisplay.textContent = freq;
    freqLabel.textContent = getFreqLabel(freq);
    freqSlider.value = freq;
    if (oscillator && isPlaying) oscillator.frequency.setValueAtTime(freq, audioContext.currentTime);
  }

  function animateBars() {
    if (!isPlaying) { bassBars.forEach(bar => bar.style.height = '20%'); return; }
    bassBars.forEach((bar, i) => {
      const dist = Math.abs(i - 5);
      bar.style.height = Math.max(20, 100 - dist * 15 - Math.random() * 20) + '%';
    });
    animationId = requestAnimationFrame(animateBars);
  }

  function playTone(freq) {
    if (!audioContext) audioContext = new (window.AudioContext || window.webkitAudioContext)();
    stopTone();
    updateDisplay(freq);
    oscillator = audioContext.createOscillator();
    gainNode = audioContext.createGain();
    oscillator.type = 'sine';
    oscillator.frequency.setValueAtTime(freq, audioContext.currentTime);
    gainNode.gain.setValueAtTime(volumeSlider.value / 100 * 0.5, audioContext.currentTime);
    oscillator.connect(gainNode);
    gainNode.connect(audioContext.destination);
    oscillator.start();
    isPlaying = true;
    playBtn.innerHTML = '<i class="bi bi-stop-fill me-2"></i>Stop';
    playBtn.classList.replace('btn-success', 'btn-danger');
    animateBars();
  }

  function stopTone() {
    if (oscillator) { oscillator.stop(); oscillator.disconnect(); oscillator = null; }
    isPlaying = false; isSweeping = false;
    playBtn.innerHTML = '<i class="bi bi-play-fill me-2"></i>Play Bass';
    playBtn.classList.replace('btn-danger', 'btn-success');
    sweepBtn.innerHTML = '<i class="bi bi-play-fill me-2"></i>Start 10s Bass Sweep (20-200 Hz)';
    sweepProgressContainer.classList.add('d-none');
    if (animationId) cancelAnimationFrame(animationId);
    bassBars.forEach(bar => bar.style.height = '20%');
  }

  function startSweep() {
    if (isSweeping) { stopTone(); return; }
    if (!audioContext) audioContext = new (window.AudioContext || window.webkitAudioContext)();
    stopTone();
    oscillator = audioContext.createOscillator();
    gainNode = audioContext.createGain();
    oscillator.type = 'sine';
    oscillator.frequency.setValueAtTime(20, audioContext.currentTime);
    oscillator.frequency.exponentialRampToValueAtTime(200, audioContext.currentTime + 10);
    gainNode.gain.setValueAtTime(volumeSlider.value / 100 * 0.5, audioContext.currentTime);
    oscillator.connect(gainNode);
    gainNode.connect(audioContext.destination);
    oscillator.start();
    isPlaying = true; isSweeping = true;
    sweepBtn.innerHTML = '<i class="bi bi-stop-fill me-2"></i>Stop Sweep';
    sweepProgressContainer.classList.remove('d-none');
    animateBars();
    const startTime = Date.now();
    const updateInterval = setInterval(() => {
      const elapsed = Date.now() - startTime;
      const progress = (elapsed / 10000) * 100;
      if (progress >= 100 || !isSweeping) { clearInterval(updateInterval); if (isSweeping) stopTone(); return; }
      sweepProgress.style.width = progress + '%';
      updateDisplay(Math.round(20 * Math.pow(10, elapsed / 10000)));
    }, 50);
  }

  playBtn.addEventListener('click', () => isPlaying ? stopTone() : playTone(parseInt(freqSlider.value)));
  freqSlider.addEventListener('input', () => updateDisplay(parseInt(freqSlider.value)));
  volumeSlider.addEventListener('input', () => {
    volumeDisplay.textContent = volumeSlider.value + '%';
    if (gainNode && isPlaying) gainNode.gain.setValueAtTime(volumeSlider.value / 100 * 0.5, audioContext.currentTime);
  });
  freqBtns.forEach(btn => btn.addEventListener('click', () => playTone(parseInt(btn.dataset.freq))));
  sweepBtn.addEventListener('click', startSweep);
});
